INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1401, 'Genesis 47:26', 'Genesis', 47, 26, '&nbsp;نو يوسف د مِصر مُلک دپاره دا يو قانون جوړ کړو چې د فصل پينځمه حِصه به د فِرعون وى. دا قانون تر اوسه پورې شته دے. خو صِرف د اِمامانو زمکې د فِرعون نۀ شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1402, 'Genesis 47:27', 'Genesis', 47, 27, '&nbsp;بنى اِسرائيل په مِصر کښې د جشن په علاقه کښې اوسېدل، چرته چې هغوئ مالدار شول او ډېر اولاد يې پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1403, 'Genesis 47:28', 'Genesis', 47, 28, '&nbsp;يعقوب په مِصر کښې اوولس کاله اوسېدو، نو د يعقوب ټول عُمر يو سل اووۀ څلوېښت کاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1404, 'Genesis 47:29', 'Genesis', 47, 29, '&nbsp;چې کله د هغۀ د مرګ وخت رانزدې شو، نو هغۀ خپل زوئ يوسف راوغوښتلو او هغۀ ته يې وفرمائيل، ”کۀ زۀ رښتيا په تا ګران يم، نو تۀ زما سره پوخ لوظ وکړه چې تۀ به ما په مِصر کښې نۀ ښخوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1405, 'Genesis 47:30', 'Genesis', 47, 30, '&nbsp;زۀ هلته ښخېدل غواړم چرته چې زما پلار نيکۀ ښخ دى. ما د مِصر نه يوسه او هلته مې ښخ کړه چرته چې هغوئ ښخ دى.“ يوسف ورته وفرمائيل، ”زۀ به هم دغه شان وکړم چې څنګه تا وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1406, 'Genesis 47:31', 'Genesis', 47, 31, '&nbsp;يعقوب ورته وفرمائيل، ”زما سره لوظ وکړه چې تۀ به هم دغه شان وکړې.“ نو يوسف ورسره لوظ وکړو. او يعقوب د خپل کټ په سر باندې سجده وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1407, 'Genesis 48:1', 'Genesis', 48, 1, '&nbsp;څۀ موده وروستو يوسف خبر شو چې د هغۀ پلار بيمار دے. نو هغۀ خپل دوه زامن، منسى او اِفرائيم روان کړل او د خپل پلار پوښتنې له ورَغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1408, 'Genesis 48:2', 'Genesis', 48, 2, '&nbsp;چې يعقوب خبر شو چې خپل زوئ يې تپوس له راغلے دے، هغۀ خپل ځان تکړه کړو او په کټ کښې نېغ کښېناستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1409, 'Genesis 48:3', 'Genesis', 48, 3, '&nbsp;يعقوب يوسف ته وفرمائيل چې، ”قادر خُدائ د کنعان د مُلک په لوز کښې ما ته راڅرګند شو او برکت يې راکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1410, 'Genesis 48:4', 'Genesis', 48, 4, '&nbsp;هغۀ ما ته وفرمائيل، ”زۀ به تا له ډېر اولاد درکړم، نو داسې ستا د اولاد نه به ډېر قومونه جوړ شى. زۀ به ستا اولاد له دا مُلک ورکوم چې همېشه دپاره د هغوئ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1411, 'Genesis 48:5', 'Genesis', 48, 5, '&nbsp;نو اوس يوسفه، چې ستا کوم دوه زامن زما د راتلو نه مخکښې په مِصر کښې پېدا شوى دى، دوئ هم زما بچى دى، اِفرائيم او منسى زما د خپلو بچو روبين او شمعون په شان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1412, 'Genesis 48:6', 'Genesis', 48, 6, '&nbsp;خو کۀ ستا نور زامن پېدا کيږى، نو هغوئ به زما نۀ شى ګڼلے، هغوئ به د اِفرائيم او د منسى نه ميراث اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1413, 'Genesis 48:7', 'Genesis', 48, 7, '&nbsp;زۀ داسې ستا د مور راحيل په خاطر کوم. چې کله زۀ د مسوپتاميه نه واپس راتلم، نو هغه اِفرات ته نزدې د کنعان په مُلک کښې زما د ډېر غم سره وفات شوه. ما هغه د اِفرات د لارې په غاړه ښخه کړه.“ اِفرات اوس د بيت‌لحم په نوم مشهور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1414, 'Genesis 48:8', 'Genesis', 48, 8, '&nbsp;چې کله يعقوب د يوسف زامن وليدل، هغۀ تپوس وکړو، ”دا څوک دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1415, 'Genesis 48:9', 'Genesis', 48, 9, '&nbsp;نو يوسف خپل پلار ته وفرمائيل، ”دا زما زامن دى، کوم چې خُدائ پاک ما له دلته په مِصر کښې راکړى دى.“ يعقوب وفرمائيل، ”دوئ ما له راوله چې د دوئ دپاره برکت وغواړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1416, 'Genesis 48:10', 'Genesis', 48, 10, '&nbsp;د ډېر عُمر په وجه د يعقوب نظر کمزورے شوے وو او د هغۀ نظر سم نۀ لګېدو. يوسف هغۀ له زامن راوستل او هغوئ يې راغاړه ويستل او ښُکل يې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1417, 'Genesis 48:11', 'Genesis', 48, 11, '&nbsp;يعقوب يوسف ته وفرمائيل، ”ما هيڅکله هم دا ګُمان نۀ وو کړے چې زۀ به بيا تا ووينم او اوس خُدائ پاک راباندې ستا بچى هم وليدل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1418, 'Genesis 48:12', 'Genesis', 48, 12, '&nbsp;بيا يوسف هغوئ د هغۀ د غېږ نه واخستل او د هغۀ په مخکښې يې د عزت نه سر ټيټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1419, 'Genesis 48:13', 'Genesis', 48, 13, '&nbsp;يوسف اِفرائيم د يعقوب ګس طرف ته او منسى د هغۀ ښى طرف ته نزدې راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1420, 'Genesis 48:14', 'Genesis', 48, 14, '&nbsp;نو يعقوب خپل لاسونه اوږدۀ کړل او خپل ښے لاس يې د اِفرائيم په سر کېښودو، اګر چې هغه کشر وو او خپل ګس لاس يې د منسى په سر کېښودو، چې هغه مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1421, 'Genesis 48:15', 'Genesis', 48, 15, '&nbsp;بيا هغۀ يوسف دپاره برکت وغوښتلو او وې فرمائيل، ”د کوم خُدائ پاک چې زما پلار نيکۀ اِبراهيم او اِسحاق خِدمت کړے دے هغه دې، دې هلکانو له برکت ورکړى، کوم خُدائ پاک چې تر ننه پورې ټول عُمر زما ساتنه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1422, 'Genesis 48:16', 'Genesis', 48, 16, '&nbsp;هغه فرښته دې دوئ له برکت ورکړى، چې هغې زۀ د هرې بدۍ نه بچ ساتلے يم. د دې هلکانو په ذريعه دې زما او زما د پلار نيکۀ اِسحاق او اِبراهيم نوم ژوندے وساتلے شى. او په زمکه دې د دوئ ډېر اولاد پېدا شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1423, 'Genesis 48:17', 'Genesis', 48, 17, '&nbsp;چې کله يوسف دا وليدل چې د هغۀ پلار خپل ښے لاس د اِفرائيم په سر اېښے دے، هغه په دې خفه شو، نو هغۀ د خپل پلار لاس اوچت کړو او د اِفرائيم د سر نه يې د منسى سر له يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1424, 'Genesis 48:18', 'Genesis', 48, 18, '&nbsp;او يوسف خپل پلار ته وفرمائيل، ”داسې نه، زما پلاره، دا مشر دے. خپل ښے لاس دۀ له په سر کېږده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1425, 'Genesis 48:19', 'Genesis', 48, 19, '&nbsp;د هغۀ پلار اِنکار وکړو او وې فرمائيل، ”ما ته پته شته، زما زويه، ما ته پته ده چې د منسى اولاد به هم يو لوئ قوم شى. خو خپل کشر ورور به د هغۀ نه لوئ وى او د هغۀ د اولاد نه به ډېر لوئ قومونه جوړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1426, 'Genesis 48:20', 'Genesis', 48, 20, '&nbsp;نو هغۀ هغوئ له په هغه ورځ برکت ورکړو، وې فرمائيل، ”بنى اِسرائيل به ستاسو نومونه استعمالوى چې کله هغوئ د برکت نوم اخلى. هغوئ به وائى، خُدائ پاک دې تاسو د اِفرائيم او منسى په شان کړى.“ نو داسې يعقوب اِفرائيم د منسى نه مخکښې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1427, 'Genesis 48:21', 'Genesis', 48, 21, '&nbsp;بيا يعقوب يوسف ته وفرمائيل، ”ګوره، زۀ مرګ ته نزدې يم، خو خُدائ پاک به ستا مل وى او تا به واپس د خپل پلار نيکۀ مُلک ته بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1428, 'Genesis 48:22', 'Genesis', 48, 22, '&nbsp;د شِکم هغه آباده علاقه چې ما د اموريانو نه د تُورې او ليندې په زور اخستې ده زۀ هغه ستا وروڼو له نۀ ورکوم بلکې تا له يې درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1429, 'Genesis 49:1', 'Genesis', 49, 1, '&nbsp;يعقوب خپل زامن راوغوښتل او ورته يې وفرمائيل، ”راغونډ شئ او زۀ به تاسو ته ووايم چې په راتلونکى وخت کښې به په تاسو څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1430, 'Genesis 49:2', 'Genesis', 49, 2, '&nbsp;راټول شئ او واورئ، اے د يعقوب زامنو. د خپل پلار اِسرائيل خبره واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1431, 'Genesis 49:3', 'Genesis', 49, 3, '&nbsp;روبين، تۀ زما مشر زوئ يې. تۀ زما د طاقت وړومبۍ مېوه يې او زما د ځوانۍ وړومبے بچے، په عزت او طاقت کښې زما د ټولو زامنو نه زيات يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1432, 'Genesis 49:4', 'Genesis', 49, 4, '&nbsp;تۀ د جوشناک سېلاب په شان يې، خو تۀ به د ټولو نه عزتمند نۀ يې، دا ځکه چې تۀ زما د بلې ښځې سره څملاستې او د خپل پلار کټ دې پليت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1433, 'Genesis 49:5', 'Genesis', 49, 5, '&nbsp;شمعون او ليوى په بدو کښې وروڼه دى. بدعملۍ کولو دپاره د خپلو تُورو نه کار اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1434, 'Genesis 49:6', 'Genesis', 49, 6, '&nbsp;د دوئ په پټو خبرو کښې به زۀ نۀ شريکېږم، او نۀ به د دوئ په ډله کښې حِصه اخلم، ځکه چې په غصه کښې دوئ خلق ووژل او دوئ هسې د خوند دپاره غوَيان ګوډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1435, 'Genesis 49:7', 'Genesis', 49, 7, '&nbsp;لعنت دې د دوئ په قهر وى، ځکه چې هغه قهر ډېر سخت وو، او لعنت دې د دوئ په غضب وى، ځکه چې دا غضب بې‌رحمه وو. زۀ به د دوئ اولاد د اِسرائيل په ټول مُلک کښې خوارۀ وارۀ کړم. زۀ به دوئ د اِسرائيلو نورو قبيلو سره ګډ‌وډ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1436, 'Genesis 49:8', 'Genesis', 49, 8, '&nbsp;يهوداه، ستا وروڼه به ستا صِفت کوى. تۀ به خپل دشمنان د مرۍ نه رانيسې. ستا وروڼه به ستا په مخکښې ټيټ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1437, 'Genesis 49:9', 'Genesis', 49, 9, '&nbsp;يهوداه، تۀ د ازمرى بچے يې، چې ښکار ووژنى او خپل غار ته راستُون شى، غزيږى او څملى. هيڅ څوک هم دا زړۀ نۀ شى کولے چې هغه راپاڅوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1438, 'Genesis 49:10', 'Genesis', 49, 10, '&nbsp;يهوداه به د مشرۍ جنډا نيسى، او د هغۀ اولاد به همېشه حکومت کوى. قومونه به هغۀ له قلنګ راوړى، او د هغۀ په مخکښې به د تابعدارۍ سره ټيټيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1439, 'Genesis 49:11', 'Genesis', 49, 11, '&nbsp;هغه خپله کوچاڼې د انګور په بوټى پورې تړى، د ټولو نه ښۀ بوټى پورې. هغه خپلې جامې د انګور په سور رس کښې وينځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1440, 'Genesis 49:12', 'Genesis', 49, 12, '&nbsp;د هغۀ سترګې د شرابو نه سرې دى، د هغۀ غاښونه د پيو نه سپين دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1441, 'Genesis 49:13', 'Genesis', 49, 13, '&nbsp;زبولون به د سيند په غاړه اوسيږى. د هغۀ د سيند غاړه به د کشتو دپاره محفوظ ځائ وى. د هغۀ علاقه به د صيدا پورې ورسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1442, 'Genesis 49:14', 'Genesis', 49, 14, '&nbsp;يساکار لکه تکړه خر دے چې د دوو بارونو په مينځ کښې اوږد اوږد څملى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1443, 'Genesis 49:15', 'Genesis', 49, 15, '&nbsp;خو چې هغۀ ته پته ولګېږى چې د هغۀ د آرام ځائ ښۀ دے او چې هغه مُلک هم ښائسته دے. نو هغه به خپله ملا بار وړلو له راښکته کړى او د نوکر په شان کار ترې اخستے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1444, 'Genesis 49:16', 'Genesis', 49, 16, '&nbsp;دان به د خپلو خلقو بادشاه وى. هغوئ به هم د اِسرائيلو د نورو قبيلو په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1445, 'Genesis 49:17', 'Genesis', 49, 17, '&nbsp;دان به د سړک د غاړې مار وى، د لارې يو خطرناک مار، چې هغه آس په پونده وچيچى، نو چې سور کس ترې په شا پرېوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1446, 'Genesis 49:18', 'Genesis', 49, 18, '&nbsp;اے مالِکه خُدايه، زۀ ستا د خلاصون په اِنتظار يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1447, 'Genesis 49:19', 'Genesis', 49, 19, '&nbsp;د ډاکوانو يوه ډله به په جاد حمله وکړى، خو هغه به راوګرځى او په هغوئ پسې به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1448, 'Genesis 49:20', 'Genesis', 49, 20, '&nbsp;د آشر زمکه به ډېر ښۀ خوراک پېدا کړى. هغه به د بادشاهانو دپاره ښۀ مزېدار خوراک تيار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1449, 'Genesis 49:21', 'Genesis', 49, 21, '&nbsp;نفتالى هوسۍ ده چې په آزادۍ سره منډې وهى، او هغه ښُکلى بچى راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1450, 'Genesis 49:22', 'Genesis', 49, 22, '&nbsp;يوسف يوه مېوه داره څانګه ده، په سپرلى کښې د مېوې نه ډکه څانګه، د هغۀ څانګې په دېوال خېژى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1451, 'Genesis 49:23', 'Genesis', 49, 23, '&nbsp;د هغۀ غصه ناک دشمنان په هغۀ باندې سخته حمله کوى او د خپلو غشو او ليندو سره په هغۀ پسې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1452, 'Genesis 49:24', 'Genesis', 49, 24, '&nbsp;خو چې هغه لينده راکاږى نو د هغۀ لاسونه نۀ رپيږى، او د هغۀ مټې مضبوطې جوړې شوې دى، د يعقوب د قادر خُدائ په قُدرت سره، د هغه شپون په نامه، چې د بنى اِسرائيلو ساتونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1453, 'Genesis 49:25', 'Genesis', 49, 25, '&nbsp;هغه ستا د پلار خُدائ پاک دے چې هغه ستا مدد کوى، هغه قادر خُدائ چې تا له برکت درکوى. د بره آسمان د بارانونو او د زمکې د لاندې د چينو برکت درکړى، برکتونه د ډېرو څاروو او د اولادونو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1454, 'Genesis 49:26', 'Genesis', 49, 26, '&nbsp;ستا د خپل پلار برکتونه همېشه دپاره د زړو غرونو د برکت نه ښۀ دى، ښۀ څيزونه د نۀ ختمېدونکو غرونو نه. دا ټول برکتونه دې د يوسف په سر وى، د هغۀ په تندى، چې د خپلو وروڼو مشر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1455, 'Genesis 49:27', 'Genesis', 49, 27, '&nbsp;بنيامين د يو شلونکى شرمخ په شان دے. چې په سحر کښې ښکار خورى او په ماښام کښې څۀ چې پاتې وى هغه ويشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1456, 'Genesis 49:28', 'Genesis', 49, 28, '&nbsp;دا د بنى اِسرائيلو دولس قبيلې دى او دا هغه وصيت دے کوم چې خپل پلار ورته د برکت ورکولو په وخت وکړو او هر زوئ له يې خپل خپل مناسب برکت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1457, 'Genesis 49:31', 'Genesis', 49, 31, '&nbsp;دا هم هغه ځائ دے چرته چې هغوئ اِبراهيم او د هغۀ ښځه ساره ښخ کړى وُو، دا هم هغه ځائ دے چرته چې هغوئ اِسحاق او د هغۀ ښځه رِبقه ښخه کړې وه، او دا هغه ځائ دے چرته چې ما لِياه ښخه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1458, 'Genesis 49:32', 'Genesis', 49, 32, '&nbsp;هغه پټے او هغه غار د حِتيانو نه اخستے شوے وو. ما هم هلته ښخ کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1459, 'Genesis 49:33', 'Genesis', 49, 33, '&nbsp;چې کله يعقوب خپلو زامنو ته وصيت ختم کړو، هغه بيا څملاستو، ساه يې ورکړه او په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
