(1463, 'Genesis 50:4', 'Genesis', 50, 4, '&nbsp;چې کله د غم وخت تېر شو، يوسف د فِرعون درباريانو ته وفرمائيل، ”کۀ تاسو ما سره ښۀ کوئ نو زۀ تاسو ته عرض کوم چې فِرعون ته داسې ووايئ چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1464, 'Genesis 50:5', 'Genesis', 50, 5, '&nbsp;چې کله زما پلار مړ کېدو، هغۀ زما نه قسم اخستے وو چې زۀ به هغه د کنعان په مُلک کښې په هغه قبر کښې ښخوم کوم چې هغۀ کنستے وو. نو مِهربانى وکړه، ما پرېږده چې زۀ خپل پلار هلته ښخ کړم او زۀ به بيا واپس راشم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
