(1467, 'Genesis 50:8', 'Genesis', 50, 8, '&nbsp;د هغۀ خاندان، د هغۀ وروڼه او د هغۀ د پلار د خاندان باقى ټول خلق د هغۀ سره لاړل. صِرف د هغوئ واړۀ ماشومان، د هغوئ ګډې، چېلۍ او څاروى د جشن په علاقه کښې پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1468, 'Genesis 50:9', 'Genesis', 50, 9, '&nbsp;په ګاډو کښې خلق او په آسونو سوارۀ خلق هم د هغۀ سره لاړل، دا يوه لويه قافله وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
