(1470, 'Genesis 50:11', 'Genesis', 50, 11, '&nbsp;چې کله د کنعان د مُلک اوسېدونکو خلقو دا وليدل چې هغه خلق د اتد په درمند کښې د غم ژړا کوى، نو هغوئ ووئيل چې، ”دا مِصريان څومره سخت د غم ژړا کوى.“ نو ځکه د هغه ځائ نوم د مِصريانو د غم ژړا مېدان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1471, 'Genesis 50:12', 'Genesis', 50, 12, '&nbsp;نو د يعقوب زامنو هم هغه شان وکړل چې څنګه هغۀ ورته وصيت کړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
